\section{Introduction}

\subsection{Boolean forms and linear equivalence}
Fix the two-element field $\FF_2 = \{0,1\}$ with $1+1 = 0$. A \emph{Boolean
function} in $n$ variables is a map $f : \FF_2^n \to \FF_2$. Every such function
has a unique \emph{algebraic normal form}, a multilinear polynomial
\[
f(x_1,\dots,x_n) = \sum_{S \subseteq \{1,\dots,n\}} a_S \prod_{i \in S} x_i,
\qquad a_S \in \FF_2,
\]
where multilinearity ($x_i^2 = x_i$) restricts each monomial to a product of
distinct variables. The \emph{degree} of $f$ is the largest $|S|$ with $a_S \ne 0$,
and the degree-$d$ layer has dimension $\binom{n}{d}$.

A \emph{cubic form} is a homogeneous degree-$3$ element. For $n = 10$ the cubic
layer has dimension $\binom{10}{3} = 120$, so there are $2^{120}$ cubic forms and
\[
|X| = 2^{120} - 1
= 1{,}329{,}227{,}995{,}784{,}915{,}872{,}903{,}807{,}060{,}280{,}344{,}575
\]
nonzero cubic forms. We write $X$ for this set throughout.

\subsection{The symmetry group and its action}
An invertible linear change of variables $x \mapsto Ax$ with $A \in \GL(n,2)$
transforms a Boolean form by substitution and re-reduction to algebraic normal
form; this preserves degree, so $\GL(n,2)$ acts on the cubic layer and on $X$. Two
forms are \emph{linearly equivalent} iff they lie in the same orbit. The cubic
layer is precisely $RM(3,n)/RM(2,n)$, linking the classification to coding theory,
cryptographic nonlinearity, and finite geometry.

\subsection{Contribution}
The known ten-variable orbit count is $3{,}691{,}560$. We do not recompute it;
instead we stress-test and explain it using only orbit--stabilizer theory,
producing a self-contained consistency certificate and a provable refutation of the
most natural wrong guess. All results avoid Burnside's orbit-counting lemma.

\section{Preliminaries: orbits and stabilizers}
Let $G$ be a finite group acting on a finite set $X$. For $x \in X$ write
$\Orb(x) = \{g\cdot x : g \in G\}$ and $\Stab(x) = \{g \in G : g\cdot x = x\}$. The
set $X$ is partitioned into orbits; let $r = |X/G|$ be their number.

\begin{theorem}[Orbit--Stabilizer]
For every $x \in X$, $\;|\Orb(x)|\cdot|\Stab(x)| = |G|$. In particular
$|\Orb(x)| \mid |G|$ and $|\Orb(x)| \le |G|$, with equality iff $\Stab(x)$ is
trivial.
\end{theorem}

An action is \emph{free} if $\Stab(x) = \{e\}$ for all $x$; an orbit of size $|G|$
is \emph{regular}.

\section{General orbit--stabilizer bounds}

\begin{theorem}[Orbit lower bound]\label{thm:lower}
For a finite group $G$ acting on a finite set $X$ with $r$ orbits,
\[
|X| \le r\,|G|, \qquad\text{equivalently}\qquad r \ge |X|/|G|.
\]
\end{theorem}
\begin{proof}
Choose a representative $x_\omega$ for each orbit $\omega$. The orbit decomposition
gives $X \cong \bigsqcup_\omega \Orb(x_\omega)$, so
$|X| = \sum_\omega |\Orb(x_\omega)|$. By orbit--stabilizer
$|\Orb(x_\omega)| = |G|/|\Stab(x_\omega)| \le |G|$, and summing over the $r$ orbits
gives $|X| \le r\,|G|$. Divide by $|G|>0$.
\end{proof}

Since $r$ is an integer, $r \ge \lceil |X|/|G|\rceil$.

\begin{theorem}[Freeness obstruction]\label{thm:free}
If the action of $G$ on $X$ is free, then $|G| \mid |X|$.
\end{theorem}
\begin{proof}
Freeness makes every orbit of size $|G|$, so $|X| = \sum_\omega |G| = r\,|G|$.
\end{proof}

\begin{corollary}\label{cor:nonfree}
If $|G| \nmid |X|$, then some $x \in X$ has $\Stab(x) \ne \{e\}$; the action is not
free.
\end{corollary}
\begin{proof}
Contrapositive of Theorem~\ref{thm:free}.
\end{proof}

\section{The order of $\GL(10,2)$}

\begin{theorem}[Order of the general linear group]\label{thm:order}
Over $\FF_2$, $\;|\GL(n,2)| = \prod_{i=0}^{n-1}(2^n - 2^i)$. In particular
\[
|\GL(10,2)| = \prod_{i=0}^{9}(2^{10}-2^{i})
= 366{,}440{,}137{,}299{,}948{,}128{,}422{,}802{,}227{,}200.
\]
\end{theorem}
\begin{proof}
An invertible matrix is an ordered basis of $\FF_2^n$. Given $i$ independent
vectors spanning a subspace of size $2^i$, the next vector may be any of the
$2^n - 2^i$ vectors outside it; the first ($i=0$) has $2^n-1$ choices. Multiply for
$i = 0,\dots,n-1$ and evaluate at $n=10$.
\end{proof}

The factor at $i=1$ is $2^{10}-2 = 1022$, so $|\GL(10,2)|$ is even.

\section{Consequences for Boolean cubic forms}
Let $G = \GL(10,2)$ act on $X$, the $2^{120}-1$ nonzero cubic forms, with $r$
orbits; the classification value is $r = 3{,}691{,}560$.

\begin{theorem}[Forced lower bound]\label{thm:forced}
$\displaystyle r \ge \left\lceil \frac{2^{120}-1}{|\GL(10,2)|} \right\rceil
= 3{,}627{,}409.$
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:lower}; numerically $(2^{120}-1)/|\GL(10,2)| = 3{,}627{,}408.6\ldots$,
whose ceiling is $3{,}627{,}409$.
\end{proof}

\begin{theorem}[Consistency certificate]\label{thm:consistency}
$3{,}691{,}560 \ge 3{,}627{,}409$, equivalently
$3{,}691{,}560 \cdot |\GL(10,2)| \ge 2^{120}-1$.
\end{theorem}
\begin{proof}
Integer comparison; the second form multiplies through by $|\GL(10,2)|$, giving
$\approx 1.3527\times10^{36} > 1.3292\times10^{36}$.
\end{proof}

\begin{theorem}[Non-freeness / disproof of the regular-action hypothesis]\label{thm:nonfree}
The action of $\GL(10,2)$ on the nonzero cubic forms is not free. Hence some
nonzero cubic form is fixed by a nontrivial linear substitution, and the count can
never equal the naive quotient $\lfloor (2^{120}-1)/|\GL(10,2)| \rfloor
= 3{,}627{,}408$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:order}, $|\GL(10,2)|$ is even; $2^{120}-1$ is odd; an even
number cannot divide an odd number, so $|\GL(10,2)| \nmid (2^{120}-1)$.
Corollary~\ref{cor:nonfree} gives a form with nontrivial stabilizer. If $r$ equaled
the floor $3{,}627{,}408$ then $r\,|G| < 2^{120}-1$ would violate
Theorem~\ref{thm:lower}.
\end{proof}

\begin{proposition}[Surplus as a stabilizer census]\label{prop:surplus}
$3{,}691{,}560 - 3{,}627{,}409 = 64{,}151$. Writing
\[
|X| = \sum_\omega \frac{|G|}{|\Stab(x_\omega)|}
= r\,|G| - \sum_\omega |G|\!\left(1 - \frac{1}{|\Stab(x_\omega)|}\right),
\]
every orbit with $|\Stab(x_\omega)| > 1$ contributes a positive correction pushing
$r$ above $|X|/|G|$. Thus the surplus is attributable to non-regular orbits---the
forms guaranteed by Theorem~\ref{thm:nonfree}.
\end{proposition}

\section{Algorithms}
\textbf{Exact group order.} Compute $|\GL(n,2)| = \prod_{i=0}^{n-1}(2^n-2^i)$ in
$O(n)$ big-integer multiplications.

\textbf{Bound certification.} With $|X| = 2^{120}-1$ and $|G| = |\GL(10,2)|$:
(1) $r_{\min} = \lceil |X|/|G|\rceil$ by integer division and remainder test;
(2) verify $r\,|G| \ge |X|$; (3) verify $|X|\bmod 2 = 1$ and $|G|\bmod 2 = 0$,
whence $|G| \nmid |X|$. All steps use exact integer arithmetic.

\section{Applications}
The cubic layer is $RM(3,n)/RM(2,n)$, so orbit classification is the classification
of Reed--Muller cosets under linear automorphisms (coding theory); cubic Boolean
functions model S-box and filter components, and linear-equivalence classes group
functions with identical affine-invariant cryptographic properties; cubic forms
over $\FF_2$ encode finite-geometric configurations. The consistency certificate
and parity obstruction serve as cheap validity checks for any purported orbit
count.

\section{Discussion}
The orbit lower bound fences the answer from below; the freeness obstruction
removes the two integer candidates nearest the naive quotient; the exact group
order supplies the constants. Together they show the count exceeds $3{,}627{,}409$
and cannot be $3{,}627{,}408$, certify $3{,}691{,}560$ as consistent, and quantify
via the surplus $64{,}151$ the contribution of symmetric forms. The general
theorems yield, as a byproduct, the $p$-group fixed-point principle: a $p$-group
acting on a set of size prime to $p$ has a fixed point.

\section{Future Directions}
\begin{enumerate}
\item \textbf{Exact orbit count from a fixed-point sum.} Build $RM(3,10)/RM(2,10)$
as a $\GL(10,2)$-module, compute the Burnside sum $\sum_g |\Fix(g)|$, and divide by
$|G|$; the conjugacy-class data on $\FF_2^{10}$ is the key ingredient.
\item \textbf{Sharper stabilizer accounting.} Establish
$\sum_x |\Stab(x)| = r\,|G|$ for the cubic layer to recover the surplus from the
non-regular orbit count.
\item \textbf{Smaller $n$ as ground truth.} Compute orbit counts for $n=4,5,6,7$
(dimensions $4,10,20,35$) by direct enumeration to validate the machinery.
\item \textbf{Generalize the bounds.} State the parity / $p$-group refinement of the
orbit lower bound and freeness obstruction for arbitrary finite group actions.
\end{enumerate}

\section{Conclusion}
Starting from the orbit lower bound, the freeness obstruction, and the exact order
of $\GL(10,2)$, we fence the number of nonzero $\GL(10,2)$-orbits of Boolean cubic
forms in ten variables into a tight window. Any correct count is at least
$3{,}627{,}409$; the value $3{,}691{,}560$ meets this floor with surplus $64{,}151$;
and a parity argument rules out $3{,}627{,}408$, proving the action is not free. The
classification value is thereby explained: as large as the elementary constraints
allow, plus the measurable contribution of forms carrying genuine symmetry.

