function GL_ORDER(n, q):
    result <- 1
    for i from 0 to n-1:
        result <- result * (q^n - q^i)
    return result

function FORCED_LOWER_BOUND(X, G):
    return ceil(X / G)            # exact integer ceiling

function CERTIFY(r, X, G):
    return r >= FORCED_LOWER_BOUND(X, G)

