def forced_orbit_lower_bound(space_size: int, group_order: int) -> int:
    """Certify the minimum number of orbits via the orbit lower bound.

    By orbit-stabilizer, each orbit has size at most |G|, so with r orbits
    |X| <= r*|G|, hence r >= ceil(|X|/|G|).  Returns the integer ceiling using
    exact integer division (no rounding error).
    """
    return -(-space_size // group_order)


def certify_consistency(claimed_orbits: int, space_size: int,
                        group_order: int) -> bool:
    """Return True iff the claimed orbit count clears the forced lower bound,
    equivalently claimed_orbits * |G| >= |X|."""
    return claimed_orbits >= forced_orbit_lower_bound(space_size, group_order)

